  "g.shuffle.d":"नंबर कीज़ हर कुछ सेकंड में जगह बदलती हैं",
  "g.ghost":"अदृश्य स्याही",
  "g.ghost.d":"लिखे नंबर थोड़ी देर में गायब हो जाते हैं — याद रखो",
  "g.ice":"बर्फ़",
  "g.ice.d":"जमे खाने पर टैप करके पहले बर्फ़ तोड़ो, फिर लिखो",
  "sc.n.0":"अपनी जगह पर",
  "sc.d.0":"एक पहेली से शुरू करो और 4×4 की आदत डालो।",
  "sc.n.1":"रेडी, सेट, गो!",
  "sc.d.1":"दो, तीन पहेलियाँ… हर बार थोड़ी ज़्यादा।",
  "sc.n.2":"दौड़",
  "sc.d.2":"आसान पहेलियों के साथ थोड़ा सोचने वाली भी।",
  "sc.n.3":"उछल-कूद",
  "sc.d.3":"हर स्टेज में ज़्यादा पहेलियाँ — लय बनाए रखो।",
  "sc.n.4":"रिले",
  "sc.d.4":"कम सुराग — बैटन आगे बढ़ाते रहो।",
  "sc.n.5":"हर्डल",
  "sc.d.5":"अगला लेवल: एक बार में 7–8 पहेलियाँ।",
  "sc.n.6":"चढ़ाई",
  "sc.d.6":"धीरे-धीरे कठिन होता कोर्स।",
  "sc.n.7":"स्की जंप",
  "sc.d.7":"कम सुराग, बड़ी छलांग।",
  "sc.n.8":"मैराथन",
  "sc.d.8":"14 तक पहेलियाँ — दम की परीक्षा।",
  "sc.n.9":"बवंडर",
  "sc.d.9":"सबसे कठिन 4×4, फटाफट।",
  "sc.n.10":"शरारती कीड़ा",
  "sc.d.10":"नंबर खाने वाला कीड़ा छूट गया! हल करते-करते भगाओ।",
  "sc.n.11":"मोज़ेक",
  "sc.d.11":"दिए गए नंबर कभी-कभी धुंधले हो जाते हैं।",
  "sc.n.12":"गोल-गोल",
  "sc.d.12":"बोर्ड घूमता रहता है — चक्कर मत खाना!",
  "sc.n.13":"स्पॉटलाइट",
  "sc.d.13":"बस रोशनी वाला हिस्सा दिखता है — बॉक्स की लकीरों पर भरोसा रखो।",
  "sc.n.14":"फलों की टोकरी",
  "sc.d.14":"नंबरों की जगह फल।",
  "sc.n.15":"की शफ़ल",
  "sc.d.15":"नंबर कीज़ हिलती रहती हैं — आदत से नहीं, आँखों से खेलो!",
  "sc.n.16":"अदृश्य स्याही",
  "sc.d.16":"तुम्हारे नंबर मिटते जाते हैं… याद रखो।",
  "sc.n.17":"बर्फ़",
  "sc.d.17":"जमे खानों को पहले टैप से तोड़ो।",
  "sc.n.18":"रहस्य कप",
  "sc.d.18":"कीड़ा, मोज़ेक, गोल-गोल और स्पॉटलाइट, सब मिक्स।",
  "sc.n.19":"सरप्राइज़ कप",
  "sc.d.19":"फल, की शफ़ल, अदृश्य स्याही और बर्फ़, सब मिक्स।",
  "sc.n.20":"सब-चलेगा कार्निवल",
  "sc.d.20":"आठों खास नियम आते हैं!",
