  "tu.d.goal":"सुडोकू में 9×9 ग्रिड को 1–9 से भरना होता है। नियम सिर्फ़ तीन हैं।",
  "tu.d.row":"नियम 1: हर पंक्ति में 1–9 एक-एक बार। पीली पंक्ति में कौन-सा नंबर गायब है?",
