  "tu.d.modes":"हर दिन तीन डेली: आसान = कांस्य, मध्यम = रजत, कठिन = स्वर्ण। मेडल जमा करो!",
  "tu.md.daily":"मेडल से कैलेंडर भरता है, लगातार रिकॉर्ड भी बनाओ",
