add('ja', {"sp.col.sub":"23コース・330ステージ","sp.tier.1.d":"変則ルールが1つずつ登場","sp.tier.2.d":"さらに3つの変則ルールが登場","sp.tier.3.d":"変則ルールを2〜4つ同時に","sp.tier.4.d":"5つ以上、最後はぜんぶ同時に","tu.s.gim":"初級からは、こんな変則ルールが登場！ 上級・達人ではいくつも同時に出てくるよ。スタート前に一行の説明が出るから安心してね。","sa.tier.d":"{t}のステージをすべてクリア","sa.gc.d":"「{g}」コースをすべてクリア","sa.perfcat.d":"どれか1コースの★をすべてそろえる","sk.n.u0":"ふしぎコンボ","sk.d.u0":"むし・モザイク・ぐるぐる・すぽっとらいとが2〜4つ同時に！","sk.n.u1":"びっくりコンボ","sk.d.u1":"くだもの・まぜまぜ・とうめい・こおりが2〜4つ同時に！","sk.n.u2":"みえないトリオ","sk.d.u2":"見えにくくなるルールばかりが重なる。目をこらして！","sk.n.u3":"てんやわんや","sk.d.u3":"入力のじゃまをするルールが重なる。あわてずに！","sk.n.u4":"なんでもミックス","sk.d.u4":"8つの中から2〜4つがランダムに組み合わさる。","sk.n.m0":"カーニバル","sk.d.m0":"5つ以上の変則ルールが一度に！ にぎやかに解こう。","sk.n.m1":"パレード","sk.d.m1":"5〜7つのルールが行進してくる。","sk.n.m2":"ハリケーン","sk.d.m2":"6つ以上、最後はぜんぶのルールが吹き荒れる。","sk.n.m3":"ウルトラマラソン","sk.d.m3":"たくさんのルールの中で、最大8問を走りきれ。","sk.n.m4":"すぴーどマスター","sk.d.m4":"最後の試練。ほぼぜんぶのルールが強めで登場。"});
add('en', {"sp.col.sub":"23 courses · 330 stages","sp.tier.1.d":"Meet the special rules one by one","sp.tier.2.d":"Three more special rules to meet","sp.tier.3.d":"2–4 special rules at once","sp.tier.4.d":"5 or more rules at once — finally all 8","tu.s.gim":"From Beginner on, special rules like these appear — in Advanced and Expert several at once! A one-line explanation shows before each start.","sa.tier.d":"Clear every {t} stage","sa.gc.d":"Clear every stage of the {g} course","sa.perfcat.d":"Get every star in any one course","sk.n.u0":"Mystery Combo","sk.d.u0":"2–4 of bug, mosaic, spin and spotlight at once!","sk.n.u1":"Surprise Combo","sk.d.u1":"2–4 of fruit, key shuffle, invisible ink and ice at once!","sk.n.u2":"Hidden Trio","sk.d.u2":"Only rules that make things hard to see, stacked up. Look closely!","sk.n.u3":"Total Chaos","sk.d.u3":"Rules that get in the way of your input, stacked up. Stay calm!","sk.n.u4":"Anything Mix","sk.d.u4":"2–4 of the eight rules, picked at random.","sk.n.m0":"Carnival","sk.d.m0":"Five or more special rules at once — a lively mess!","sk.n.m1":"Parade","sk.d.m1":"Five to seven rules come marching in.","sk.n.m2":"Hurricane","sk.d.m2":"Six or more, and finally every rule blowing at once.","sk.n.m3":"Ultra Marathon","sk.d.m3":"Run up to 8 puzzles through a storm of rules.","sk.n.m4":"Speed Master","sk.d.m4":"The final trial: nearly every rule, at full strength."});
