add('zh', {"sp.col.sub":"23条路线 · 330关","sp.tier.1.d":"特殊规则逐个登场","sp.tier.2.d":"再来3个新的特殊规则","sp.tier.3.d":"2~4个特殊规则同时出现","sp.tier.4.d":"5个以上，最后全部一起上","tu.s.gim":"从初级开始会出现这些特殊规则！到了高级和达人，还会好几个同时出现哦。开始前会有一行说明，放心吧。","sa.tier.d":"通关所有{t}关卡","sa.gc.d":"通关「{g}」路线的全部关卡","sa.perfcat.d":"集齐任意一条路线的全部★","sk.n.u0":"奇妙组合","sk.d.u0":"捣蛋虫、马赛克、转呀转、聚光灯，2~4个同时来！","sk.n.u1":"惊喜组合","sk.d.u1":"水果、乱乱键、隐形墨水、冰块，2~4个同时来！","sk.n.u2":"看不见三重奏","sk.d.u2":"全是让你看不清的规则叠在一起。睁大眼睛！","sk.n.u3":"手忙脚乱","sk.d.u3":"全是妨碍输入的规则叠在一起。别慌！","sk.n.u4":"大杂烩","sk.d.u4":"从8个规则中随机组合2~4个。","sk.n.m0":"嘉年华","sk.d.m0":"5个以上特殊规则一起来！热热闹闹地解吧。","sk.n.m1":"大游行","sk.d.m1":"5~7个规则排队游行而来。","sk.n.m2":"飓风","sk.d.m2":"6个以上，最后所有规则一起狂风大作。","sk.n.m3":"超级马拉松","sk.d.m3":"在一堆规则中，跑完最多8道题。","sk.n.m4":"速度大师","sk.d.m4":"最终试炼。几乎所有规则都以强化版登场。"});
add('ko', {"sp.col.sub":"23코스 · 330스테이지","sp.tier.1.d":"특수 규칙이 하나씩 등장","sp.tier.2.d":"특수 규칙 3개가 더 등장","sp.tier.3.d":"특수 규칙 2~4개가 동시에","sp.tier.4.d":"5개 이상, 마지막엔 전부 동시에","tu.s.gim":"초급부터 이런 특수 규칙이 등장해요! 상급·달인에서는 여러 개가 동시에 나와요. 시작 전에 한 줄 설명이 나오니 안심하세요.","sa.tier.d":"{t} 스테이지 모두 클리어","sa.gc.d":"「{g}」 코스 모두 클리어","sa.perfcat.d":"아무 코스 하나의 ★을 모두 모으기","sk.n.u0":"신기한 콤보","sk.d.u0":"방해벌레·모자이크·빙글빙글·스포트라이트 중 2~4개가 동시에!","sk.n.u1":"깜짝 콤보","sk.d.u1":"과일·뒤죽박죽 키·투명 잉크·얼음 중 2~4개가 동시에!","sk.n.u2":"안 보이는 트리오","sk.d.u2":"잘 안 보이게 하는 규칙만 겹쳐요. 눈을 크게 떠요!","sk.n.u3":"우당탕탕","sk.d.u3":"입력을 방해하는 규칙이 겹쳐요. 침착하게!","sk.n.u4":"뭐든지 믹스","sk.d.u4":"8개 중 2~4개가 랜덤으로 조합돼요.","sk.n.m0":"카니발","sk.d.m0":"특수 규칙 5개 이상이 한꺼번에! 신나게 풀어요.","sk.n.m1":"퍼레이드","sk.d.m1":"5~7개의 규칙이 행진해 와요.","sk.n.m2":"허리케인","sk.d.m2":"6개 이상, 마지막엔 모든 규칙이 휘몰아쳐요.","sk.n.m3":"울트라 마라톤","sk.d.m3":"수많은 규칙 속에서 최대 8문제를 완주하라.","sk.n.m4":"스피드 마스터","sk.d.m4":"마지막 시련. 거의 모든 규칙이 강하게 등장."});
add('es', {"sp.col.sub":"23 recorridos · 330 fases","sp.tier.1.d":"Conoce las reglas especiales una a una","sp.tier.2.d":"Tres reglas especiales más","sp.tier.3.d":"2–4 reglas especiales a la vez","sp.tier.4.d":"5 o más reglas a la vez — al final, las 8","tu.s.gim":"¡Desde Principiante aparecen reglas especiales como estas, y en Avanzado y Experto, varias a la vez! Antes de empezar verás una explicación de una línea.","sa.tier.d":"Supera todas las fases de {t}","sa.gc.d":"Supera todas las fases del recorrido {g}","sa.perfcat.d":"Consigue todas las estrellas de un recorrido","sk.n.u0":"Combo misterio","sk.d.u0":"¡De 2 a 4 entre Bichito, Mosaico, Vueltas y Foco a la vez!","sk.n.u1":"Combo sorpresa","sk.d.u1":"¡De 2 a 4 entre Frutas, Teclas locas, Tinta invisible y Hielo a la vez!","sk.n.u2":"Trío oculto","sk.d.u2":"Solo reglas que dificultan la vista, apiladas. ¡Fíjate bien!","sk.n.u3":"Caos total","sk.d.u3":"Reglas que estorban al escribir, apiladas. ¡Calma!","sk.n.u4":"Mezcla libre","sk.d.u4":"De 2 a 4 de las ocho reglas, al azar.","sk.n.m0":"Carnaval","sk.d.m0":"¡Cinco o más reglas especiales a la vez! Un lío muy divertido.","sk.n.m1":"Desfile","sk.d.m1":"De cinco a siete reglas llegan desfilando.","sk.n.m2":"Huracán","sk.d.m2":"Seis o más y, al final, todas las reglas soplando a la vez.","sk.n.m3":"Ultramaratón","sk.d.m3":"Resuelve hasta 8 sudokus entre un montón de reglas.","sk.n.m4":"Maestro veloz","sk.d.m4":"La prueba final: casi todas las reglas, a toda potencia."});
add('fr', {"sp.col.sub":"23 parcours · 330 niveaux","sp.tier.1.d":"Les règles spéciales, une à une","sp.tier.2.d":"Encore trois règles spéciales","sp.tier.3.d":"2 à 4 règles spéciales à la fois","sp.tier.4.d":"5 règles ou plus — puis les 8 à la fois","tu.s.gim":"Dès Débutant, des règles spéciales comme celles-ci apparaissent — et en Avancé et Expert, plusieurs à la fois ! Une explication d'une ligne s'affiche avant chaque départ.","sa.tier.d":"Termine tous les niveaux {t}","sa.gc.d":"Termine tout le parcours « {g} »","sa.perfcat.d":"Obtiens toutes les étoiles d'un parcours","sk.n.u0":"Combo mystère","sk.d.u0":"2 à 4 parmi Insecte farceur, Mosaïque, Toupie et Projecteur !","sk.n.u1":"Combo surprise","sk.d.u1":"2 à 4 parmi Fruits, Touches folles, Encre invisible et Glace !","sk.n.u2":"Trio invisible","sk.d.u2":"Que des règles qui gênent la vue, empilées. Ouvre l'œil !","sk.n.u3":"Gros bazar","sk.d.u3":"Des règles qui gênent la saisie, empilées. Du calme !","sk.n.u4":"Méli-mélo","sk.d.u4":"2 à 4 des huit règles, tirées au hasard.","sk.n.m0":"Carnaval","sk.d.m0":"Cinq règles spéciales ou plus d'un coup ! Joyeux bazar.","sk.n.m1":"Parade","sk.d.m1":"Cinq à sept règles arrivent en défilé.","sk.n.m2":"Ouragan","sk.d.m2":"Six ou plus, et à la fin toutes les règles déchaînées.","sk.n.m3":"Ultra-marathon","sk.d.m3":"Enchaîne jusqu'à 8 grilles dans une tempête de règles.","sk.n.m4":"Maître de vitesse","sk.d.m4":"L'épreuve finale : presque toutes les règles, à fond."});
add('pt', {"sp.col.sub":"23 percursos · 330 fases","sp.tier.1.d":"Conheça as regras especiais uma a uma","sp.tier.2.d":"Mais três regras especiais","sp.tier.3.d":"2–4 regras especiais de uma vez","sp.tier.4.d":"5 ou mais regras juntas — no fim, todas as 8","tu.s.gim":"A partir do Iniciante, aparecem regras especiais como estas — no Avançado e no Expert, várias de uma vez! Antes de cada partida aparece uma explicação de uma linha.","sa.tier.d":"Complete todas as fases {t}","sa.gc.d":"Complete todas as fases do percurso {g}","sa.perfcat.d":"Pegue todas as estrelas de um percurso","sk.n.u0":"Combo mistério","sk.d.u0":"De 2 a 4 entre Bichinho, Mosaico, Gira-gira e Holofote de uma vez!","sk.n.u1":"Combo surpresa","sk.d.u1":"De 2 a 4 entre Frutas, Teclas malucas, Tinta invisível e Gelo de uma vez!","sk.n.u2":"Trio oculto","sk.d.u2":"Só regras que atrapalham a visão, empilhadas. Olho vivo!","sk.n.u3":"Caos total","sk.d.u3":"Regras que atrapalham a digitação, empilhadas. Calma!","sk.n.u4":"Mistura geral","sk.d.u4":"De 2 a 4 das oito regras, sorteadas.","sk.n.m0":"Carnaval","sk.d.m0":"Cinco ou mais regras especiais de uma vez! Uma bagunça animada.","sk.n.m1":"Desfile","sk.d.m1":"De cinco a sete regras chegam desfilando.","sk.n.m2":"Furacão","sk.d.m2":"Seis ou mais e, no fim, todas as regras soprando juntas.","sk.n.m3":"Ultramaratona","sk.d.m3":"Resolva até 8 sudokus em meio a uma tempestade de regras.","sk.n.m4":"Mestre da velocidade","sk.d.m4":"O desafio final: quase todas as regras, com força total."});
add('de', {"sp.col.sub":"23 Kurse · 330 Stufen","sp.tier.1.d":"Die Sonderregeln, eine nach der anderen","sp.tier.2.d":"Drei weitere Sonderregeln","sp.tier.3.d":"2–4 Sonderregeln gleichzeitig","sp.tier.4.d":"5 oder mehr Regeln — am Ende alle 8","tu.s.gim":"Ab Anfänger kommen Sonderregeln wie diese — bei Fortgeschritten und Profi sogar mehrere gleichzeitig! Vor jedem Start gibt's eine kurze Erklärung.","sa.tier.d":"Schaffe alle Stufen in {t}","sa.gc.d":"Schaffe alle Stufen im Kurs „{g}“","sa.perfcat.d":"Hol alle Sterne in einem Kurs","sk.n.u0":"Rätsel-Combo","sk.d.u0":"2–4 aus Nervkäfer, Mosaik, Ringelreihen und Scheinwerfer gleichzeitig!","sk.n.u1":"Überraschungs-Combo","sk.d.u1":"2–4 aus Obst, Tastensalat, Zaubertinte und Eis gleichzeitig!","sk.n.u2":"Unsichtbar-Trio","sk.d.u2":"Nur Regeln, die die Sicht stören, gestapelt. Genau hinsehen!","sk.n.u3":"Totales Chaos","sk.d.u3":"Regeln, die beim Eingeben stören, gestapelt. Ruhig bleiben!","sk.n.u4":"Wildmix","sk.d.u4":"2–4 der acht Regeln, zufällig gemischt.","sk.n.m0":"Karneval","sk.d.m0":"Fünf oder mehr Sonderregeln auf einmal — ein buntes Durcheinander!","sk.n.m1":"Parade","sk.d.m1":"Fünf bis sieben Regeln marschieren heran.","sk.n.m2":"Hurrikan","sk.d.m2":"Sechs oder mehr — am Ende toben alle Regeln zugleich.","sk.n.m3":"Ultramarathon","sk.d.m3":"Löse bis zu 8 Rätsel im Regelsturm.","sk.n.m4":"Tempo-Meister","sk.d.m4":"Die letzte Prüfung: fast alle Regeln, volle Stärke."});
add('hi', {"sp.col.sub":"23 कोर्स · 330 स्टेज","sp.tier.1.d":"खास नियम एक-एक करके आते हैं","sp.tier.2.d":"तीन और नए खास नियम","sp.tier.3.d":"एक साथ 2–4 खास नियम","sp.tier.4.d":"5 या ज़्यादा नियम — आखिर में सारे 8","tu.s.gim":"आसान से ही ऐसे खास नियम आने लगते हैं — कठिन और उस्ताद में तो कई एक साथ! हर शुरुआत से पहले एक लाइन की जानकारी मिलेगी।","sa.tier.d":"{t} की सारी स्टेज पार करो","sa.gc.d":"{g} कोर्स की सारी स्टेज पार करो","sa.perfcat.d":"किसी एक कोर्स के सारे ★ जुटाओ","sk.n.u0":"रहस्य कॉम्बो","sk.d.u0":"शरारती कीड़ा, मोज़ेक, गोल-गोल और स्पॉटलाइट में से 2–4 एक साथ!","sk.n.u1":"सरप्राइज़ कॉम्बो","sk.d.u1":"फल, की शफ़ल, अदृश्य स्याही और बर्फ़ में से 2–4 एक साथ!","sk.n.u2":"छुपी तिकड़ी","sk.d.u2":"सिर्फ़ दिखना मुश्किल करने वाले नियम, एक के ऊपर एक। ध्यान से देखो!","sk.n.u3":"धमाचौकड़ी","sk.d.u3":"इनपुट में रुकावट डालने वाले नियम, एक के ऊपर एक। घबराना मत!","sk.n.u4":"सब कुछ मिक्स","sk.d.u4":"आठ में से 2–4 नियम, बिल्कुल रैंडम।","sk.n.m0":"कार्निवल","sk.d.m0":"एक साथ 5 या ज़्यादा खास नियम! मज़े से हल करो।","sk.n.m1":"परेड","sk.d.m1":"5 से 7 नियम परेड करते हुए आते हैं।","sk.n.m2":"तूफ़ान","sk.d.m2":"6 या ज़्यादा, और आखिर में सारे नियमों की आँधी।","sk.n.m3":"अल्ट्रा मैराथन","sk.d.m3":"ढेर सारे नियमों के बीच 8 पहेलियों तक दौड़ते रहो।","sk.n.m4":"स्पीड मास्टर","sk.d.m4":"आखिरी इम्तिहान: लगभग सारे नियम, पूरी ताकत से।"});
add('ar', {"sp.col.sub":"23 مسارًا · 330 مرحلة","sp.tier.1.d":"تعرّف على القواعد الخاصة واحدة تلو الأخرى","sp.tier.2.d":"ثلاث قواعد خاصة أخرى","sp.tier.3.d":"من 2 إلى 4 قواعد خاصة معًا","sp.tier.4.d":"5 قواعد أو أكثر — وفي النهاية الثماني كلها","tu.s.gim":"من مستوى مبتدئ تظهر قواعد خاصة مثل هذه — وفي متقدم وخبير عدة قواعد معًا! يظهر شرح من سطر واحد قبل كل بداية.","sa.tier.d":"أكمل كل مراحل {t}","sa.gc.d":"أكمل كل مراحل مسار «{g}»","sa.perfcat.d":"اجمع كل النجوم في أي مسار","sk.n.u0":"كومبو الغموض","sk.d.u0":"من 2 إلى 4 من الحشرة المزعجة والفسيفساء والدوّامة وبقعة الضوء معًا!","sk.n.u1":"كومبو المفاجأة","sk.d.u1":"من 2 إلى 4 من الفواكه والمفاتيح المخلوطة والحبر الخفي والجليد معًا!","sk.n.u2":"الثلاثي الخفي","sk.d.u2":"قواعد تحجب الرؤية فقط، فوق بعضها. دقّق النظر!","sk.n.u3":"فوضى عارمة","sk.d.u3":"قواعد تعرقل الإدخال، فوق بعضها. اهدأ!","sk.n.u4":"خلطة عشوائية","sk.d.u4":"من 2 إلى 4 من القواعد الثماني، عشوائيًا.","sk.n.m0":"كرنفال","sk.d.m0":"خمس قواعد خاصة أو أكثر معًا! فوضى مرحة.","sk.n.m1":"استعراض","sk.d.m1":"من خمس إلى سبع قواعد تأتي في موكب.","sk.n.m2":"إعصار","sk.d.m2":"ست قواعد أو أكثر، وفي النهاية تعصف كل القواعد معًا.","sk.n.m3":"ماراثون خارق","sk.d.m3":"حُلّ حتى 8 ألغاز وسط عاصفة من القواعد.","sk.n.m4":"سيد السرعة","sk.d.m4":"التحدي الأخير: كل القواعد تقريبًا، بأقصى قوة."});
// key shuffle: on-screen keys only
add('ja', {"g.shuffle.d": "数字キーの並びがときどき入れかわる。キーボードとフリックは使えず、画面のキーだけ"});
add('en', {"g.shuffle.d": "The number keys swap places now and then — only the on-screen keys work (no keyboard or flick)"});
add('zh', {"g.shuffle.d": "数字键的位置会不时交换。不能用键盘和滑动输入，只能点屏幕上的键"});
add('ko', {"g.shuffle.d": "숫자 키 위치가 가끔 바뀌어요. 키보드·플릭은 안 되고 화면 키만 써요"});
add('es', {"g.shuffle.d": "Las teclas numéricas cambian de sitio — solo valen las de la pantalla (sin teclado ni deslizar)"});
add('fr', {"g.shuffle.d": "Les touches changent de place — seules celles de l'écran marchent (ni clavier ni glisser)"});
add('pt', {"g.shuffle.d": "As teclas trocam de lugar — só valem as da tela (sem teclado nem deslizar)"});
add('de', {"g.shuffle.d": "Die Zifferntasten tauschen die Plätze — nur die Tasten am Bildschirm gehen (keine Tastatur, kein Wischen)"});
add('hi', {"g.shuffle.d": "अंक बटन बीच-बीच में जगह बदलते हैं — सिर्फ़ स्क्रीन के बटन चलेंगे (कीबोर्ड और फ़्लिक नहीं)"});
add('ar', {"g.shuffle.d": "تتبدّل أماكن أزرار الأرقام — تعمل أزرار الشاشة فقط (بلا لوحة مفاتيح ولا سحب)"});
