add('ja', {"g.bomb":"ばくだん","g.bomb.d":"空きマスにばくだん！ 火が消える前にうめないと −3秒","g.swap":"いれかわり","g.swap.d":"同じ太線の中の2列がときどき入れかわる。書いた数字もいっしょに動くよ","sk.n.bomb":"ばくだん","sk.d.bomb":"ばくだんのついたマスを先にうめよう。のんびりしてるとドカン！","sk.n.swap":"いれかわり","sk.d.swap":"列がするっと入れかわる。どこが動いたか見のがさないで！","sp.tier.2.d":"さらに5つの変則ルールが登場","sp.col.sub":"25コース・350ステージ","sk.d.u4":"10この中から2〜4つがランダムに組み合わさる。","sa.gall.d":"10この変則ルールをすべて体験"});
add('en', {"g.bomb":"Bomb","g.bomb.d":"A bomb sits on an empty cell — fill it before the fuse burns out or lose 3 seconds","g.swap":"Swap","g.swap.d":"Two rows or columns inside the same thick lines trade places — your numbers move with them","sk.n.bomb":"Bomb","sk.d.bomb":"Fill the cell with the bomb first — dawdle and it goes boom!","sk.n.swap":"Swap","sk.d.swap":"Rows slide into each other's places. Don't miss what moved!","sp.tier.2.d":"Five more special rules to meet","sp.col.sub":"25 courses · 350 stages","sk.d.u4":"2–4 of the ten rules, picked at random.","sa.gall.d":"Try all ten special rules"});
// update
add('zh', {"g.bomb":"炸弹","g.bomb.d":"空格上出现炸弹！引线烧完前填好，不然 −3秒","g.swap":"换换位","g.swap.d":"同一粗线框内的两行或两列会突然换位，写好的数字也一起移动哦","sk.n.bomb":"炸弹","sk.d.bomb":"先填带炸弹的格子吧。慢吞吞的话就会砰！","sk.n.swap":"换换位","sk.d.swap":"行列会悄悄换位。别漏看哪里动了！","sp.tier.2.d":"再来5个新的特殊规则","sp.col.sub":"25条路线 · 350关","sk.d.u4":"从10个规则中随机组合2~4个。","sa.gall.d":"体验全部10种特殊规则"});
add('ko', {"g.bomb":"폭탄","g.bomb.d":"빈칸에 폭탄이! 불이 꺼지기 전에 채우지 않으면 −3초","g.swap":"바꿔치기","g.swap.d":"같은 굵은 선 안의 두 줄이 가끔 자리를 바꿔요. 쓴 숫자도 같이 움직여요","sk.n.bomb":"폭탄","sk.d.bomb":"폭탄이 붙은 칸부터 채우자. 느긋하게 있다간 펑!","sk.n.swap":"바꿔치기","sk.d.swap":"줄이 스르륵 자리를 바꿔요. 어디가 움직였는지 놓치지 마요!","sp.tier.2.d":"특수 규칙 5개가 더 등장","sp.col.sub":"25코스 · 350스테이지","sk.d.u4":"10개 중 2~4개가 랜덤으로 조합돼요.","sa.gall.d":"10가지 특수 규칙을 모두 체험"});
add('es', {"g.bomb":"Bomba","g.bomb.d":"¡Una bomba en una casilla vacía! Rellénala antes de que se acabe la mecha o pierdes 3 s","g.swap":"Cambiazo","g.swap.d":"Dos filas o columnas dentro de las mismas líneas gruesas se intercambian, y tus números van con ellas","sk.n.bomb":"Bomba","sk.d.bomb":"Rellena primero la casilla con bomba. Si te duermes… ¡bum!","sk.n.swap":"Cambiazo","sk.d.swap":"Las filas cambian de sitio. ¡No pierdas de vista qué se movió!","sp.tier.2.d":"Cinco reglas especiales más","sp.col.sub":"25 recorridos · 350 fases","sk.d.u4":"De 2 a 4 de las diez reglas, al azar.","sa.gall.d":"Prueba las diez reglas especiales"});
add('fr', {"g.bomb":"Bombe","g.bomb.d":"Une bombe sur une case vide ! Remplis-la avant que la mèche s'éteigne, sinon −3 s","g.swap":"Échange","g.swap.d":"Deux lignes ou colonnes d'un même bloc échangent leur place — tes chiffres bougent avec","sk.n.bomb":"Bombe","sk.d.bomb":"Remplis d'abord la case piégée. Traîne trop et… boum !","sk.n.swap":"Échange","sk.d.swap":"Les lignes glissent et changent de place. Repère ce qui a bougé !","sp.tier.2.d":"Encore cinq règles spéciales","sp.col.sub":"25 parcours · 350 niveaux","sk.d.u4":"2 à 4 des dix règles, tirées au hasard.","sa.gall.d":"Essaie les dix règles spéciales"});
add('pt', {"g.bomb":"Bomba","g.bomb.d":"Uma bomba numa casa vazia! Preencha antes do pavio acabar ou perca 3 s","g.swap":"Troca-troca","g.swap.d":"Duas linhas ou colunas dentro das mesmas linhas grossas trocam de lugar — seus números vão junto","sk.n.bomb":"Bomba","sk.d.bomb":"Preencha primeiro a casa com a bomba. Se enrolar… bum!","sk.n.swap":"Troca-troca","sk.d.swap":"As linhas trocam de lugar de mansinho. Não perca o que mudou!","sp.tier.2.d":"Mais cinco regras especiais","sp.col.sub":"25 percursos · 350 fases","sk.d.u4":"De 2 a 4 das dez regras, sorteadas.","sa.gall.d":"Experimente as dez regras especiais"});
add('de', {"g.bomb":"Bombe","g.bomb.d":"Eine Bombe auf einem leeren Feld! Füll es, bevor die Lunte abbrennt, sonst −3 s","g.swap":"Platztausch","g.swap.d":"Zwei Zeilen oder Spalten im selben dicken Rahmen tauschen den Platz — deine Zahlen wandern mit","sk.n.bomb":"Bombe","sk.d.bomb":"Füll zuerst das Feld mit der Bombe. Wer trödelt, macht bumm!","sk.n.swap":"Platztausch","sk.d.swap":"Zeilen rutschen auf neue Plätze. Merk dir, was sich bewegt hat!","sp.tier.2.d":"Fünf weitere Sonderregeln","sp.col.sub":"25 Kurse · 350 Stufen","sk.d.u4":"2–4 der zehn Regeln, zufällig gemischt.","sa.gall.d":"Probier alle zehn Sonderregeln aus"});
add('hi', {"g.bomb":"बम","g.bomb.d":"खाली खाने पर बम! फ़्यूज़ बुझने से पहले भरो, वरना −3 सेकंड","g.swap":"अदला-बदली","g.swap.d":"एक ही मोटी लाइन के अंदर की दो पंक्तियाँ या कॉलम जगह बदलते हैं — तुम्हारे अंक भी साथ चलते हैं","sk.n.bomb":"बम","sk.d.bomb":"पहले बम वाला खाना भरो। देर की तो धमाका!","sk.n.swap":"अदला-बदली","sk.d.swap":"पंक्तियाँ चुपके से जगह बदलती हैं। देखो क्या हिला!","sp.tier.2.d":"पाँच और नए खास नियम","sp.col.sub":"25 कोर्स · 350 स्टेज","sk.d.u4":"दस में से 2–4 नियम, बिल्कुल रैंडम।","sa.gall.d":"दसों खास नियम आज़माओ"});
add('ar', {"g.bomb":"قنبلة","g.bomb.d":"قنبلة على خانة فارغة! املأها قبل أن ينطفئ الفتيل وإلا تخسر 3 ثوانٍ","g.swap":"تبديل","g.swap.d":"يتبادل صفّان أو عمودان داخل نفس الخطوط السميكة مكانيهما — وتتحرك أرقامك معهما","sk.n.bomb":"قنبلة","sk.d.bomb":"املأ خانة القنبلة أولًا. إن تباطأت… بوم!","sk.n.swap":"تبديل","sk.d.swap":"تنزلق الصفوف وتتبادل أماكنها. لا تفوّت ما تحرّك!","sp.tier.2.d":"خمس قواعد خاصة أخرى","sp.col.sub":"25 مسارًا · 350 مرحلة","sk.d.u4":"من 2 إلى 4 من القواعد العشر، عشوائيًا.","sa.gall.d":"جرّب القواعد الخاصة العشر كلها"});
// update
add('ja', {"sp.tier.3.d":"変則ルールが2つ同時に（後半は3つ）","sp.tier.4.d":"強めの変則ルールが3つ同時に（最後は4つ）","sk.d.u0":"むし・モザイク・ぐるぐる・すぽっとらいとが2〜3つ同時に！","sk.d.u1":"くだもの・まぜまぜ・とうめい・こおり・いれかわりが2〜3つ同時に！","sk.d.u4":"10この中から2〜3つがランダムに組み合わさる。","sk.d.m0":"2〜3つの変則ルールが一度に！ にぎやかに解こう。","sk.d.m1":"2〜3つの強めのルールが行進してくる。","sk.d.m2":"いつでも3つのルールが吹き荒れる。","sk.d.m4":"最後の試練。3〜4つのルールが強めで登場。","tu.s.gim":"初級からは、こんな変則ルールが登場！ 上級・達人では2〜3つ同時に出てくるよ。スタート前に一行の説明が出るから安心してね。"});
add('en', {"sp.tier.3.d":"2 special rules at once (3 later on)","sp.tier.4.d":"3 strong rules at once (up to 4 at the very end)","sk.d.u0":"2–3 of bug, mosaic, spin and spotlight at once!","sk.d.u1":"2–3 of fruit, key shuffle, invisible ink, ice and swap at once!","sk.d.u4":"2–3 of the ten rules, picked at random.","sk.d.m0":"2–3 special rules at once — a lively mess!","sk.d.m1":"2–3 strong rules come marching in.","sk.d.m2":"Three rules blowing at all times.","sk.d.m4":"The final trial: 3–4 rules at full strength.","tu.s.gim":"From Beginner on, special rules like these appear — in Advanced and Expert, 2–3 at once! A one-line explanation shows before each start."});
// update
add('zh', {"sp.tier.3.d":"2个特殊规则同时出现（后半段3个）","sp.tier.4.d":"3个强化规则同时出现（最后4个）","sk.d.u0":"捣蛋虫、马赛克、转呀转、聚光灯，2~3个同时来！","sk.d.u1":"水果、乱乱键、隐形墨水、冰块、换换位，2~3个同时来！","sk.d.u4":"从10个规则中随机组合2~3个。","sk.d.m0":"2~3个特殊规则一起来！热热闹闹地解吧。","sk.d.m1":"2~3个强化规则排队游行而来。","sk.d.m2":"始终有3个规则狂风大作。","sk.d.m4":"最终试炼。3~4个规则以强化版登场。","tu.s.gim":"从初级开始会出现这些特殊规则！到了高级和达人，会有2~3个同时出现哦。开始前会有一行说明，放心吧。"});
add('ko', {"sp.tier.3.d":"특수 규칙 2개가 동시에 (후반엔 3개)","sp.tier.4.d":"강한 규칙 3개가 동시에 (마지막엔 4개)","sk.d.u0":"방해벌레·모자이크·빙글빙글·스포트라이트 중 2~3개가 동시에!","sk.d.u1":"과일·뒤죽박죽 키·투명 잉크·얼음·바꿔치기 중 2~3개가 동시에!","sk.d.u4":"10개 중 2~3개가 랜덤으로 조합돼요.","sk.d.m0":"특수 규칙 2~3개가 한꺼번에! 신나게 풀어요.","sk.d.m1":"강한 규칙 2~3개가 행진해 와요.","sk.d.m2":"언제나 3개의 규칙이 휘몰아쳐요.","sk.d.m4":"마지막 시련. 규칙 3~4개가 강하게 등장.","tu.s.gim":"초급부터 이런 특수 규칙이 등장해요! 상급·달인에서는 2~3개가 동시에 나와요. 시작 전에 한 줄 설명이 나오니 안심하세요."});
add('es', {"sp.tier.3.d":"2 reglas especiales a la vez (3 más adelante)","sp.tier.4.d":"3 reglas fuertes a la vez (hasta 4 al final)","sk.d.u0":"¡De 2 a 3 entre Bichito, Mosaico, Vueltas y Foco a la vez!","sk.d.u1":"¡De 2 a 3 entre Frutas, Teclas locas, Tinta invisible, Hielo y Cambiazo a la vez!","sk.d.u4":"De 2 a 3 de las diez reglas, al azar.","sk.d.m0":"¡De 2 a 3 reglas especiales a la vez! Un lío muy divertido.","sk.d.m1":"De 2 a 3 reglas fuertes llegan desfilando.","sk.d.m2":"Tres reglas soplando todo el tiempo.","sk.d.m4":"La prueba final: de 3 a 4 reglas, a toda potencia.","tu.s.gim":"¡Desde Principiante aparecen reglas especiales como estas, y en Avanzado y Experto, de 2 a 3 a la vez! Antes de empezar verás una explicación de una línea."});
add('fr', {"sp.tier.3.d":"2 règles spéciales à la fois (3 ensuite)","sp.tier.4.d":"3 règles corsées à la fois (jusqu'à 4 à la fin)","sk.d.u0":"2 ou 3 parmi Insecte farceur, Mosaïque, Toupie et Projecteur !","sk.d.u1":"2 ou 3 parmi Fruits, Touches folles, Encre invisible, Glace et Échange !","sk.d.u4":"2 ou 3 des dix règles, tirées au hasard.","sk.d.m0":"2 ou 3 règles spéciales d'un coup ! Joyeux bazar.","sk.d.m1":"2 ou 3 règles corsées arrivent en défilé.","sk.d.m2":"Trois règles déchaînées en permanence.","sk.d.m4":"L'épreuve finale : 3 ou 4 règles, à fond.","tu.s.gim":"Dès Débutant, des règles spéciales comme celles-ci apparaissent — et en Avancé et Expert, 2 ou 3 à la fois ! Une explication d'une ligne s'affiche avant chaque départ."});
add('pt', {"sp.tier.3.d":"2 regras especiais de uma vez (3 mais adiante)","sp.tier.4.d":"3 regras fortes juntas (até 4 no fim)","sk.d.u0":"De 2 a 3 entre Bichinho, Mosaico, Gira-gira e Holofote de uma vez!","sk.d.u1":"De 2 a 3 entre Frutas, Teclas malucas, Tinta invisível, Gelo e Troca-troca de uma vez!","sk.d.u4":"De 2 a 3 das dez regras, sorteadas.","sk.d.m0":"De 2 a 3 regras especiais de uma vez! Uma bagunça animada.","sk.d.m1":"De 2 a 3 regras fortes chegam desfilando.","sk.d.m2":"Três regras soprando o tempo todo.","sk.d.m4":"O desafio final: de 3 a 4 regras, com força total.","tu.s.gim":"A partir do Iniciante, aparecem regras especiais como estas — no Avançado e no Expert, de 2 a 3 de uma vez! Antes de cada partida aparece uma explicação de uma linha."});
add('de', {"sp.tier.3.d":"2 Sonderregeln gleichzeitig (später 3)","sp.tier.4.d":"3 starke Regeln gleichzeitig (am Ende bis zu 4)","sk.d.u0":"2–3 aus Nervkäfer, Mosaik, Ringelreihen und Scheinwerfer gleichzeitig!","sk.d.u1":"2–3 aus Obst, Tastensalat, Zaubertinte, Eis und Platztausch gleichzeitig!","sk.d.u4":"2–3 der zehn Regeln, zufällig gemischt.","sk.d.m0":"2–3 Sonderregeln auf einmal — ein buntes Durcheinander!","sk.d.m1":"2–3 starke Regeln marschieren heran.","sk.d.m2":"Drei Regeln toben die ganze Zeit.","sk.d.m4":"Die letzte Prüfung: 3–4 Regeln, volle Stärke.","tu.s.gim":"Ab Anfänger kommen Sonderregeln wie diese — bei Fortgeschritten und Profi sogar 2–3 gleichzeitig! Vor jedem Start gibt's eine kurze Erklärung."});
add('hi', {"sp.tier.3.d":"एक साथ 2 खास नियम (बाद में 3)","sp.tier.4.d":"एक साथ 3 तगड़े नियम (आखिर में 4 तक)","sk.d.u0":"शरारती कीड़ा, मोज़ेक, गोल-गोल और स्पॉटलाइट में से 2–3 एक साथ!","sk.d.u1":"फल, की शफ़ल, अदृश्य स्याही, बर्फ़ और अदला-बदली में से 2–3 एक साथ!","sk.d.u4":"दस में से 2–3 नियम, बिल्कुल रैंडम।","sk.d.m0":"एक साथ 2–3 खास नियम! मज़े से हल करो।","sk.d.m1":"2–3 तगड़े नियम परेड करते हुए आते हैं।","sk.d.m2":"हर वक़्त 3 नियमों की आँधी।","sk.d.m4":"आखिरी इम्तिहान: 3–4 नियम, पूरी ताकत से।","tu.s.gim":"आसान से ही ऐसे खास नियम आने लगते हैं — कठिन और उस्ताद में तो 2–3 एक साथ! हर शुरुआत से पहले एक लाइन की जानकारी मिलेगी।"});
add('ar', {"sp.tier.3.d":"قاعدتان خاصتان معًا (ثم 3 لاحقًا)","sp.tier.4.d":"3 قواعد قوية معًا (حتى 4 في النهاية)","sk.d.u0":"من 2 إلى 3 من الحشرة المزعجة والفسيفساء والدوّامة وبقعة الضوء معًا!","sk.d.u1":"من 2 إلى 3 من الفواكه والمفاتيح المخلوطة والحبر الخفي والجليد والتبديل معًا!","sk.d.u4":"من 2 إلى 3 من القواعد العشر، عشوائيًا.","sk.d.m0":"من 2 إلى 3 قواعد خاصة معًا! فوضى مرحة.","sk.d.m1":"من 2 إلى 3 قواعد قوية تأتي في موكب.","sk.d.m2":"ثلاث قواعد تعصف طوال الوقت.","sk.d.m4":"التحدي الأخير: من 3 إلى 4 قواعد، بأقصى قوة.","tu.s.gim":"من مستوى مبتدئ تظهر قواعد خاصة مثل هذه — وفي متقدم وخبير من 2 إلى 3 قواعد معًا! يظهر شرح من سطر واحد قبل كل بداية."});
/* 5 more special rules (cloud / calc / card / mole / upside) and the 中級＋ tier */
add('ja', {"g.cloud": "くもり", "g.cloud.d": "雲がふわふわ流れてきて、下のマスをかくす。雲の下にも書けるよ", "sk.n.cloud": "くもり", "sk.d.cloud": "雲のすきまから盤面をのぞこう。", "g.calc": "けいさん", "g.calc.d": "最初からある数字が「1+2」のような式に。答えがその数字", "sk.n.calc": "けいさん", "sk.d.calc": "式をパッと計算！ 頭の体操コース。", "g.card": "うらがえし", "g.card.d": "最初からある数字がカードの裏に。タップすると少しだけめくれる", "sk.n.card": "うらがえし", "sk.d.card": "どこに何があったか、覚えながら解こう。", "g.mole": "もぐら", "g.mole.d": "空きマスからもぐらが顔を出す。タップしておいはらおう", "sk.n.mole": "もぐら", "sk.d.mole": "ぴょこっと出たらすぐポン！", "g.upside": "さかさま", "g.upside.d": "数字が横や逆さまにくるっと回る。向きにまどわされないで", "sk.n.upside": "さかさま", "sk.d.upside": "ひっくり返った数字を読みとろう。", "sp.tier.5": "中級＋", "sp.tier.5.d": "さらに5つの新しい変則ルール", "sp.col.sub": "30コース・400ステージ", "sa.gall.d": "15この変則ルールをすべて体験"});
add('en', {"g.cloud": "Cloudy", "g.cloud.d": "Clouds drift by and hide the cells beneath — you can still write under them", "sk.n.cloud": "Cloudy", "sk.d.cloud": "Peek at the board between the clouds.", "g.calc": "Math", "g.calc.d": "Given numbers become little sums like 1+2 — the answer is the number", "sk.n.calc": "Math", "sk.d.calc": "Quick mental math — a brain workout!", "g.card": "Face Down", "g.card.d": "Given numbers turn into face-down cards — tap one for a quick peek", "sk.n.card": "Face Down", "sk.d.card": "Remember where everything was as you solve.", "g.mole": "Moles", "g.mole.d": "Moles pop out of empty cells — tap them away", "sk.n.mole": "Moles", "sk.d.mole": "When one pops up — bonk!", "g.upside": "Topsy-Turvy", "g.upside.d": "Numbers turn sideways or upside down — don't let it fool you", "sk.n.upside": "Topsy-Turvy", "sk.d.upside": "Read the flipped-around numbers.", "sp.tier.5": "Intermediate+", "sp.tier.5.d": "Five more brand-new special rules", "sp.col.sub": "30 courses · 400 stages", "sa.gall.d": "Try all fifteen special rules"});
add('zh', {"g.cloud": "多云", "g.cloud.d": "云朵飘过来遮住下面的格子，云下面也能写哦", "sk.n.cloud": "多云", "sk.d.cloud": "从云缝里偷看盘面。", "g.calc": "算一算", "g.calc.d": "原有数字变成「1+2」这样的算式，答案就是那个数字", "sk.n.calc": "算一算", "sk.d.calc": "快速心算！动脑体操路线。", "g.card": "翻牌", "g.card.d": "原有数字变成背面朝上的卡片，点一下能翻开看一小会儿", "sk.n.card": "翻牌", "sk.d.card": "边记住位置边解题。", "g.mole": "打地鼠", "g.mole.d": "地鼠从空格里冒出来，点一下赶走它", "sk.n.mole": "打地鼠", "sk.d.mole": "一冒头就敲！", "g.upside": "颠倒", "g.upside.d": "数字会转成横的或倒过来，别被方向迷惑", "sk.n.upside": "颠倒", "sk.d.upside": "认出翻转过来的数字。", "sp.tier.5": "中级＋", "sp.tier.5.d": "再来5个全新的特殊规则", "sp.col.sub": "30条路线 · 400关", "sa.gall.d": "体验全部15个特殊规则"});
add('ko', {"g.cloud": "흐림", "g.cloud.d": "구름이 둥실 흘러와 아래 칸을 가려요. 구름 밑에도 쓸 수 있어요", "sk.n.cloud": "흐림", "sk.d.cloud": "구름 사이로 판을 엿보자.", "g.calc": "계산", "g.calc.d": "처음부터 있는 숫자가 「1+2」 같은 식으로! 답이 그 숫자예요", "sk.n.calc": "계산", "sk.d.calc": "식을 바로 계산! 두뇌 체조 코스.", "g.card": "뒤집기", "g.card.d": "처음부터 있는 숫자가 뒤집힌 카드로. 탭하면 잠깐 보여요", "sk.n.card": "뒤집기", "sk.d.card": "어디에 뭐가 있었는지 기억하며 풀자.", "g.mole": "두더지", "g.mole.d": "빈칸에서 두더지가 쏙! 탭해서 쫓아내요", "sk.n.mole": "두더지", "sk.d.mole": "튀어나오면 바로 콩!", "g.upside": "거꾸로", "g.upside.d": "숫자가 옆으로 눕거나 거꾸로 뒤집혀요. 방향에 속지 마요", "sk.n.upside": "거꾸로", "sk.d.upside": "뒤집힌 숫자를 읽어내자.", "sp.tier.5": "중급＋", "sp.tier.5.d": "새로운 특수 규칙 5개가 더", "sp.col.sub": "30코스 · 400스테이지", "sa.gall.d": "특수 규칙 15개 모두 체험"});
add('es', {"g.cloud": "Nublado", "g.cloud.d": "Pasan nubes que tapan las casillas — puedes escribir debajo igual", "sk.n.cloud": "Nublado", "sk.d.cloud": "Asómate al tablero entre las nubes.", "g.calc": "Cuentas", "g.calc.d": "Los números iniciales se vuelven cuentas como 1+2 — el resultado es el número", "sk.n.calc": "Cuentas", "sk.d.calc": "¡Cálculo rápido! Gimnasia mental.", "g.card": "Boca abajo", "g.card.d": "Los números iniciales son cartas boca abajo — tócalas para echar un vistazo", "sk.n.card": "Boca abajo", "sk.d.card": "Recuerda dónde estaba cada número.", "g.mole": "Topos", "g.mole.d": "Salen topos de las casillas vacías — tócalos para echarlos", "sk.n.mole": "Topos", "sk.d.mole": "¡Si asoma, golpe!", "g.upside": "Patas arriba", "g.upside.d": "Los números giran de lado o boca abajo — que no te engañen", "sk.n.upside": "Patas arriba", "sk.d.upside": "Lee los números dados la vuelta.", "sp.tier.5": "Intermedio+", "sp.tier.5.d": "Cinco reglas especiales nuevas más", "sp.col.sub": "30 recorridos · 400 fases", "sa.gall.d": "Prueba las quince reglas especiales"});
add('fr', {"g.cloud": "Nuageux", "g.cloud.d": "Des nuages passent et cachent les cases — tu peux écrire dessous", "sk.n.cloud": "Nuageux", "sk.d.cloud": "Jette un œil entre les nuages.", "g.calc": "Calcul", "g.calc.d": "Les chiffres donnés deviennent des calculs comme 1+2 — le résultat est le chiffre", "sk.n.calc": "Calcul", "sk.d.calc": "Calcul éclair ! Gym pour le cerveau.", "g.card": "Face cachée", "g.card.d": "Les chiffres donnés sont des cartes face cachée — touche-en une pour jeter un œil", "sk.n.card": "Face cachée", "sk.d.card": "Retiens où était chaque chiffre.", "g.mole": "Taupes", "g.mole.d": "Des taupes sortent des cases vides — tape-les pour les chasser", "sk.n.mole": "Taupes", "sk.d.mole": "Elle sort ? Bonk !", "g.upside": "Sens dessus dessous", "g.upside.d": "Les chiffres tournent sur le côté ou à l'envers — ne te laisse pas piéger", "sk.n.upside": "Sens dessus dessous", "sk.d.upside": "Lis les chiffres retournés.", "sp.tier.5": "Intermédiaire+", "sp.tier.5.d": "Cinq nouvelles règles spéciales", "sp.col.sub": "30 parcours · 400 niveaux", "sa.gall.d": "Essaie les quinze règles spéciales"});
add('pt', {"g.cloud": "Nublado", "g.cloud.d": "Nuvens passam e escondem as casas — dá para escrever embaixo", "sk.n.cloud": "Nublado", "sk.d.cloud": "Espie o tabuleiro entre as nuvens.", "g.calc": "Continhas", "g.calc.d": "Os números iniciais viram contas como 1+2 — o resultado é o número", "sk.n.calc": "Continhas", "sk.d.calc": "Cálculo rápido! Ginástica para o cérebro.", "g.card": "Virado", "g.card.d": "Os números iniciais viram cartas viradas — toque para espiar um pouco", "sk.n.card": "Virado", "sk.d.card": "Lembre onde estava cada número.", "g.mole": "Toupeiras", "g.mole.d": "Toupeiras saem das casas vazias — toque para espantá-las", "sk.n.mole": "Toupeiras", "sk.d.mole": "Apareceu? Pá!", "g.upside": "De ponta-cabeça", "g.upside.d": "Os números giram de lado ou de ponta-cabeça — não se confunda", "sk.n.upside": "De ponta-cabeça", "sk.d.upside": "Leia os números virados.", "sp.tier.5": "Intermediário+", "sp.tier.5.d": "Mais cinco regras especiais novas", "sp.col.sub": "30 percursos · 400 fases", "sa.gall.d": "Experimente as quinze regras especiais"});
add('de', {"g.cloud": "Wolkig", "g.cloud.d": "Wolken ziehen vorbei und verdecken Felder — darunter kannst du trotzdem schreiben", "sk.n.cloud": "Wolkig", "sk.d.cloud": "Späh zwischen den Wolken aufs Feld.", "g.calc": "Rechnen", "g.calc.d": "Vorgegebene Zahlen werden zu Aufgaben wie 1+2 — das Ergebnis ist die Zahl", "sk.n.calc": "Rechnen", "sk.d.calc": "Blitzrechnen! Gehirnjogging.", "g.card": "Verdeckt", "g.card.d": "Vorgegebene Zahlen sind verdeckte Karten — tippe für einen kurzen Blick", "sk.n.card": "Verdeckt", "sk.d.card": "Merk dir, wo was lag.", "g.mole": "Maulwürfe", "g.mole.d": "Maulwürfe tauchen in leeren Feldern auf — tipp sie weg", "sk.n.mole": "Maulwürfe", "sk.d.mole": "Taucht einer auf — bonk!", "g.upside": "Kopfstand", "g.upside.d": "Zahlen drehen sich zur Seite oder stehen kopf — lass dich nicht täuschen", "sk.n.upside": "Kopfstand", "sk.d.upside": "Lies die verdrehten Zahlen.", "sp.tier.5": "Mittel+", "sp.tier.5.d": "Fünf weitere neue Sonderregeln", "sp.col.sub": "30 Kurse · 400 Stufen", "sa.gall.d": "Probiere alle fünfzehn Sonderregeln"});
add('hi', {"g.cloud": "बादल", "g.cloud.d": "बादल तैरते हुए आते हैं और खाने छुपा देते हैं — उनके नीचे भी लिख सकते हो", "sk.n.cloud": "बादल", "sk.d.cloud": "बादलों के बीच से बोर्ड देखो।", "g.calc": "हिसाब", "g.calc.d": "पहले से दिए अंक 1+2 जैसे सवाल बन जाते हैं — जवाब ही वह अंक है", "sk.n.calc": "हिसाब", "sk.d.calc": "झटपट हिसाब! दिमाग़ की कसरत।", "g.card": "उल्टे पत्ते", "g.card.d": "पहले से दिए अंक उल्टे पत्ते बन जाते हैं — टैप करो तो पल भर दिखेंगे", "sk.n.card": "उल्टे पत्ते", "sk.d.card": "याद रखो कहाँ क्या था।", "g.mole": "छछूंदर", "g.mole.d": "खाली खानों से छछूंदर झाँकते हैं — टैप करके भगाओ", "sk.n.mole": "छछूंदर", "sk.d.mole": "निकले तो फ़ौरन ठक!", "g.upside": "उल्टा-पुल्टा", "g.upside.d": "अंक तिरछे या उल्टे घूम जाते हैं — दिशा से धोखा मत खाना", "sk.n.upside": "उल्टा-पुल्टा", "sk.d.upside": "घूमे हुए अंक पहचानो।", "sp.tier.5": "मध्यम+", "sp.tier.5.d": "पाँच और नए खास नियम", "sp.col.sub": "30 कोर्स · 400 स्टेज", "sa.gall.d": "सारे पंद्रह खास नियम आज़माओ"});
add('ar', {"g.cloud": "غائم", "g.cloud.d": "غيوم تمرّ وتخفي الخانات — يمكنك الكتابة تحتها", "sk.n.cloud": "غائم", "sk.d.cloud": "اختلس النظر إلى اللوحة بين الغيوم.", "g.calc": "حساب", "g.calc.d": "الأرقام المعطاة تصبح عمليات مثل 1+2 — الناتج هو الرقم", "sk.n.calc": "حساب", "sk.d.calc": "حساب سريع! تمرين للعقل.", "g.card": "بطاقات مقلوبة", "g.card.d": "الأرقام المعطاة تصبح بطاقات مقلوبة — المس واحدة لتلقي نظرة سريعة", "sk.n.card": "بطاقات مقلوبة", "sk.d.card": "تذكّر مكان كل رقم.", "g.mole": "الخُلد", "g.mole.d": "حيوانات الخُلد تطلّ من الخانات الفارغة — المسها لإبعادها", "sk.n.mole": "الخُلد", "sk.d.mole": "إن ظهر — بُم!", "g.upside": "رأسًا على عقب", "g.upside.d": "الأرقام تدور جانبًا أو رأسًا على عقب — لا تنخدع", "sk.n.upside": "رأسًا على عقب", "sk.d.upside": "اقرأ الأرقام المقلوبة.", "sp.tier.5": "متوسط+", "sp.tier.5.d": "خمس قواعد خاصة جديدة أخرى", "sp.col.sub": "30 مسارًا · 400 مرحلة", "sa.gall.d": "جرّب القواعد الخاصة الخمس عشرة"});
/* 10 more special rules (balloon … sleepy), the チャレンジ tier, combos over all 25 rules */
add('ja', {"g.balloon": "ふうせん", "g.balloon.d": "ふうせんが下からふわふわ。タップでパンとわろう", "sk.n.balloon": "ふうせん", "sk.d.balloon": "ふうせんをわりながら解こう！", "g.dark": "ていでん", "g.dark.d": "ときどき電気が消えて真っ暗に。暗くても書けるよ", "sk.n.dark": "ていでん", "sk.d.dark": "パッと消えても、あわてずに。", "g.sway": "ゆらゆら", "g.sway.d": "盤面が船みたいにゆらゆらゆれる", "sk.n.sway": "ゆらゆら", "sk.d.sway": "ゆれる盤面で、よくねらって。", "g.paint": "ペンキ", "g.paint.d": "ペンキがベチャッとマスをかくす。タップでふきとろう", "sk.n.paint": "ペンキ", "sk.d.paint": "ペンキをふきながらスピード勝負！", "g.order": "じゅんばん", "g.order.d": "番号のついたマスは1、2、3…の順にしかうめられない", "sk.n.order": "じゅんばん", "sk.d.order": "どの順番でうめるか、作戦が大事。", "g.noline": "わくなし", "g.noline.d": "太い線（★2からは全部の線）が消える。箱の場所を思い出して", "sk.n.noline": "わくなし", "sk.d.noline": "線がなくても、4×4の形を見ぬこう。", "g.star": "ながれぼし", "g.star.d": "ながれぼしをタップでキャッチすると+2秒！", "sk.n.star": "ながれぼし", "sk.d.star": "星をつかまえて時間をかせごう！", "g.rev": "あまのじゃく", "g.rev.d": "キーが反対の数字を入力する（1↔4、2↔3）", "sk.n.rev": "あまのじゃく", "sk.d.rev": "あたまの中で数字をひっくり返そう。", "g.dice": "さいころ", "g.dice.d": "数字がさいころの目になる。点の数をかぞえて", "sk.n.dice": "さいころ", "sk.d.dice": "目の数をパッと読みとろう。", "g.sleepy": "ねむねむ", "g.sleepy.d": "入力が止まると盤面がだんだん眠って暗くなる。書き続けて起こそう", "sk.n.sleepy": "ねむねむ", "sk.d.sleepy": "手を止めたら、おやすみなさい…", "sp.tier.6": "チャレンジ", "sp.tier.6.d": "さらに10この新しい変則ルール", "sp.col.sub": "40コース・500ステージ", "sa.gall.d": "25この変則ルールをすべて体験", "sk.d.u0": "動き回るルールが2〜3つ同時に！", "sk.d.u1": "数字の見え方や入力が変わるルールが2〜3つ同時に！", "sk.d.u4": "25この中から2〜3つがランダムに組み合わさる。"});
add('en', {"g.balloon": "Balloons", "g.balloon.d": "Balloons float up over the board — tap to pop them", "sk.n.balloon": "Balloons", "sk.d.balloon": "Pop balloons as you solve!", "g.dark": "Power Cut", "g.dark.d": "Every so often the lights go out — you can still write in the dark", "sk.n.dark": "Power Cut", "sk.d.dark": "Lights out? Don't panic.", "g.sway": "Rocking Boat", "g.sway.d": "The board rocks back and forth like a boat", "sk.n.sway": "Rocking Boat", "sk.d.sway": "Aim carefully on a rocking board.", "g.paint": "Paint", "g.paint.d": "Paint splats cover cells — tap to wipe them off", "sk.n.paint": "Paint", "sk.d.paint": "Wipe the paint and race on!", "g.order": "In Order", "g.order.d": "Numbered cells can only be filled 1, 2, 3 … in order", "sk.n.order": "In Order", "sk.d.order": "Plan which cell to fill when.", "g.noline": "No Lines", "g.noline.d": "The box lines (from ★2, all lines) vanish — remember where the boxes are", "sk.n.noline": "No Lines", "sk.d.noline": "See the 4×4 shape without the lines.", "g.star": "Shooting Stars", "g.star.d": "Tap a shooting star to catch it for +2 seconds!", "sk.n.star": "Shooting Stars", "sk.d.star": "Catch stars to win extra time!", "g.rev": "Contrary Keys", "g.rev.d": "The keys type the opposite number (1↔4, 2↔3)", "sk.n.rev": "Contrary Keys", "sk.d.rev": "Flip the numbers in your head.", "g.dice": "Dice", "g.dice.d": "Numbers turn into dice — count the dots", "sk.n.dice": "Dice", "sk.d.dice": "Read the dots in a flash.", "g.sleepy": "Sleepy", "g.sleepy.d": "Stop writing and the board dozes off and dims — keep going to wake it", "sk.n.sleepy": "Sleepy", "sk.d.sleepy": "Pause too long and it's nighty-night…", "sp.tier.6": "Challenge", "sp.tier.6.d": "Ten more brand-new special rules", "sp.col.sub": "40 courses · 500 stages", "sa.gall.d": "Try all 25 special rules", "sk.d.u0": "2–3 rules that move around, at once!", "sk.d.u1": "2–3 rules that change how numbers look or type, at once!", "sk.d.u4": "2–3 of the 25 rules, picked at random."});
add('zh', {"g.balloon": "气球", "g.balloon.d": "气球从下面飘上来，点一下就啪地戳破", "sk.n.balloon": "气球", "sk.d.balloon": "边戳气球边解题！", "g.dark": "停电", "g.dark.d": "时不时会停电变黑，黑暗中也能写", "sk.n.dark": "停电", "sk.d.dark": "突然变黑也别慌。", "g.sway": "摇摇晃晃", "g.sway.d": "盘面像小船一样摇来摇去", "sk.n.sway": "摇摇晃晃", "sk.d.sway": "在摇晃的盘面上瞄准。", "g.paint": "油漆", "g.paint.d": "油漆啪地盖住格子，点一下擦掉", "sk.n.paint": "油漆", "sk.d.paint": "边擦油漆边比速度！", "g.order": "按顺序", "g.order.d": "带编号的格子只能按1、2、3…的顺序填", "sk.n.order": "按顺序", "sk.d.order": "先填哪里？战略很重要。", "g.noline": "无框线", "g.noline.d": "粗线（★2起所有线）会消失，记住宫的位置", "sk.n.noline": "无框线", "sk.d.noline": "没有线也要看出4×4的形状。", "g.star": "流星", "g.star.d": "点中流星就能+2秒！", "sk.n.star": "流星", "sk.d.star": "抓住星星，赚取时间！", "g.rev": "唱反调", "g.rev.d": "按键会输入相反的数字（1↔4、2↔3）", "sk.n.rev": "唱反调", "sk.d.rev": "在脑中把数字反过来。", "g.dice": "骰子", "g.dice.d": "数字变成骰子点数，数一数点", "sk.n.dice": "骰子", "sk.d.dice": "一眼读出点数。", "g.sleepy": "困困", "g.sleepy.d": "停止输入，盘面就会慢慢睡着变暗，继续写来叫醒它", "sk.n.sleepy": "困困", "sk.d.sleepy": "手一停，就晚安了…", "sp.tier.6": "挑战", "sp.tier.6.d": "再来10个全新的特殊规则", "sp.col.sub": "40条路线 · 500关", "sa.gall.d": "体验全部25个特殊规则", "sk.d.u0": "会动的规则2~3个同时来！", "sk.d.u1": "改变数字外观或输入的规则2~3个同时来！", "sk.d.u4": "从25个规则中随机组合2~3个。"});
add('ko', {"g.balloon": "풍선", "g.balloon.d": "풍선이 아래에서 둥실둥실. 탭해서 펑 터뜨려요", "sk.n.balloon": "풍선", "sk.d.balloon": "풍선을 터뜨리며 풀자!", "g.dark": "정전", "g.dark.d": "가끔 불이 꺼져 깜깜해져요. 어두워도 쓸 수 있어요", "sk.n.dark": "정전", "sk.d.dark": "갑자기 꺼져도 당황하지 마요.", "g.sway": "흔들흔들", "g.sway.d": "판이 배처럼 흔들흔들 흔들려요", "sk.n.sway": "흔들흔들", "sk.d.sway": "흔들리는 판에서 잘 노려요.", "g.paint": "페인트", "g.paint.d": "페인트가 철퍽 칸을 가려요. 탭해서 닦아내요", "sk.n.paint": "페인트", "sk.d.paint": "페인트를 닦으며 스피드 승부!", "g.order": "순서대로", "g.order.d": "번호가 붙은 칸은 1, 2, 3… 순서로만 채울 수 있어요", "sk.n.order": "순서대로", "sk.d.order": "어떤 순서로 채울지 작전이 중요해요.", "g.noline": "테두리 없음", "g.noline.d": "굵은 선(★2부터는 모든 선)이 사라져요. 박스 위치를 기억해요", "sk.n.noline": "테두리 없음", "sk.d.noline": "선이 없어도 4×4 모양을 찾아내자.", "g.star": "별똥별", "g.star.d": "별똥별을 탭해서 잡으면 +2초!", "sk.n.star": "별똥별", "sk.d.star": "별을 잡아 시간을 벌자!", "g.rev": "청개구리", "g.rev.d": "키가 반대 숫자를 입력해요(1↔4, 2↔3)", "sk.n.rev": "청개구리", "sk.d.rev": "머릿속에서 숫자를 뒤집자.", "g.dice": "주사위", "g.dice.d": "숫자가 주사위 눈이 돼요. 점을 세어 봐요", "sk.n.dice": "주사위", "sk.d.dice": "눈의 수를 한눈에 읽자.", "g.sleepy": "졸음", "g.sleepy.d": "입력을 멈추면 판이 점점 졸려서 어두워져요. 계속 써서 깨워요", "sk.n.sleepy": "졸음", "sk.d.sleepy": "손을 멈추면 잘 자요…", "sp.tier.6": "챌린지", "sp.tier.6.d": "새로운 특수 규칙 10개가 더", "sp.col.sub": "40코스 · 500스테이지", "sa.gall.d": "특수 규칙 25개 모두 체험", "sk.d.u0": "움직이는 규칙 2~3개가 동시에!", "sk.d.u1": "숫자의 모양이나 입력이 바뀌는 규칙 2~3개가 동시에!", "sk.d.u4": "25개 중 2~3개가 랜덤으로 조합돼요."});
add('es', {"g.balloon": "Globos", "g.balloon.d": "Suben globos por el tablero — tócalos para reventarlos", "sk.n.balloon": "Globos", "sk.d.balloon": "¡Revienta globos mientras resuelves!", "g.dark": "Apagón", "g.dark.d": "De vez en cuando se va la luz — puedes escribir a oscuras", "sk.n.dark": "Apagón", "sk.d.dark": "¿Se apagó? Sin pánico.", "g.sway": "Barquito", "g.sway.d": "El tablero se balancea como un barco", "sk.n.sway": "Barquito", "sk.d.sway": "Apunta bien en un tablero que se mece.", "g.paint": "Pintura", "g.paint.d": "Manchas de pintura tapan casillas — tócalas para limpiarlas", "sk.n.paint": "Pintura", "sk.d.paint": "¡Limpia la pintura y sigue corriendo!", "g.order": "En orden", "g.order.d": "Las casillas numeradas solo se rellenan en orden: 1, 2, 3…", "sk.n.order": "En orden", "sk.d.order": "Planea qué casilla rellenar y cuándo.", "g.noline": "Sin líneas", "g.noline.d": "Las líneas de los cuadros (desde ★2, todas) desaparecen — recuerda dónde están", "sk.n.noline": "Sin líneas", "sk.d.noline": "Ve la forma 4×4 sin líneas.", "g.star": "Estrellas fugaces", "g.star.d": "¡Toca una estrella fugaz para ganar +2 segundos!", "sk.n.star": "Estrellas fugaces", "sk.d.star": "¡Atrapa estrellas para ganar tiempo!", "g.rev": "Teclas al revés", "g.rev.d": "Las teclas escriben el número opuesto (1↔4, 2↔3)", "sk.n.rev": "Teclas al revés", "sk.d.rev": "Da la vuelta a los números en tu cabeza.", "g.dice": "Dados", "g.dice.d": "Los números se vuelven dados — cuenta los puntos", "sk.n.dice": "Dados", "sk.d.dice": "Lee los puntos de un vistazo.", "g.sleepy": "Dormilón", "g.sleepy.d": "Si dejas de escribir, el tablero se duerme y oscurece — sigue para despertarlo", "sk.n.sleepy": "Dormilón", "sk.d.sleepy": "Si paras mucho, a dormir…", "sp.tier.6": "Desafío", "sp.tier.6.d": "Diez reglas especiales nuevas más", "sp.col.sub": "40 recorridos · 500 fases", "sa.gall.d": "Prueba las 25 reglas especiales", "sk.d.u0": "¡2–3 reglas que se mueven, a la vez!", "sk.d.u1": "¡2–3 reglas que cambian cómo se ven o se escriben los números!", "sk.d.u4": "De 2 a 3 de las 25 reglas, al azar."});
add('fr', {"g.balloon": "Ballons", "g.balloon.d": "Des ballons montent sur la grille — touche-les pour les éclater", "sk.n.balloon": "Ballons", "sk.d.balloon": "Éclate des ballons en résolvant !", "g.dark": "Panne de courant", "g.dark.d": "De temps en temps, la lumière s'éteint — tu peux écrire dans le noir", "sk.n.dark": "Panne de courant", "sk.d.dark": "Tout s'éteint ? Pas de panique.", "g.sway": "Roulis", "g.sway.d": "La grille tangue comme un bateau", "sk.n.sway": "Roulis", "sk.d.sway": "Vise bien sur une grille qui tangue.", "g.paint": "Peinture", "g.paint.d": "Des taches de peinture cachent des cases — touche pour essuyer", "sk.n.paint": "Peinture", "sk.d.paint": "Essuie la peinture et fonce !", "g.order": "Dans l'ordre", "g.order.d": "Les cases numérotées se remplissent seulement dans l'ordre 1, 2, 3…", "sk.n.order": "Dans l'ordre", "sk.d.order": "Choisis bien quand remplir chaque case.", "g.noline": "Sans lignes", "g.noline.d": "Les lignes des carrés (dès ★2, toutes) disparaissent — retiens où sont les carrés", "sk.n.noline": "Sans lignes", "sk.d.noline": "Vois la forme 4×4 sans lignes.", "g.star": "Étoiles filantes", "g.star.d": "Touche une étoile filante pour gagner +2 secondes !", "sk.n.star": "Étoiles filantes", "sk.d.star": "Attrape des étoiles pour gagner du temps !", "g.rev": "Touches contraires", "g.rev.d": "Les touches écrivent le chiffre opposé (1↔4, 2↔3)", "sk.n.rev": "Touches contraires", "sk.d.rev": "Retourne les chiffres dans ta tête.", "g.dice": "Dés", "g.dice.d": "Les chiffres deviennent des dés — compte les points", "sk.n.dice": "Dés", "sk.d.dice": "Lis les points en un éclair.", "g.sleepy": "Somnolence", "g.sleepy.d": "Arrête d'écrire et la grille s'endort et s'assombrit — continue pour la réveiller", "sk.n.sleepy": "Somnolence", "sk.d.sleepy": "Trop de pause ? Bonne nuit…", "sp.tier.6": "Défi", "sp.tier.6.d": "Dix nouvelles règles spéciales", "sp.col.sub": "40 parcours · 500 niveaux", "sa.gall.d": "Essaie les 25 règles spéciales", "sk.d.u0": "2 à 3 règles qui bougent, à la fois !", "sk.d.u1": "2 à 3 règles qui changent l'aspect ou la saisie des chiffres !", "sk.d.u4": "2 à 3 des 25 règles, tirées au hasard."});
add('pt', {"g.balloon": "Balões", "g.balloon.d": "Balões sobem pelo tabuleiro — toque para estourar", "sk.n.balloon": "Balões", "sk.d.balloon": "Estoure balões enquanto resolve!", "g.dark": "Apagão", "g.dark.d": "De vez em quando a luz apaga — dá para escrever no escuro", "sk.n.dark": "Apagão", "sk.d.dark": "Apagou? Sem pânico.", "g.sway": "Barquinho", "g.sway.d": "O tabuleiro balança como um barco", "sk.n.sway": "Barquinho", "sk.d.sway": "Mire bem num tabuleiro que balança.", "g.paint": "Tinta", "g.paint.d": "Manchas de tinta cobrem casas — toque para limpar", "sk.n.paint": "Tinta", "sk.d.paint": "Limpe a tinta e corra!", "g.order": "Em ordem", "g.order.d": "Casas numeradas só podem ser preenchidas na ordem 1, 2, 3…", "sk.n.order": "Em ordem", "sk.d.order": "Planeje qual casa preencher e quando.", "g.noline": "Sem linhas", "g.noline.d": "As linhas dos quadrados (a partir de ★2, todas) somem — lembre onde ficam", "sk.n.noline": "Sem linhas", "sk.d.noline": "Veja a forma 4×4 sem as linhas.", "g.star": "Estrelas cadentes", "g.star.d": "Toque numa estrela cadente para ganhar +2 segundos!", "sk.n.star": "Estrelas cadentes", "sk.d.star": "Pegue estrelas para ganhar tempo!", "g.rev": "Teclas do contra", "g.rev.d": "As teclas digitam o número oposto (1↔4, 2↔3)", "sk.n.rev": "Teclas do contra", "sk.d.rev": "Inverta os números na cabeça.", "g.dice": "Dados", "g.dice.d": "Os números viram dados — conte os pontinhos", "sk.n.dice": "Dados", "sk.d.dice": "Leia os pontos num instante.", "g.sleepy": "Soneca", "g.sleepy.d": "Se parar de escrever, o tabuleiro cochila e escurece — continue para acordá-lo", "sk.n.sleepy": "Soneca", "sk.d.sleepy": "Parou demais? Boa noite…", "sp.tier.6": "Desafio", "sp.tier.6.d": "Mais dez regras especiais novas", "sp.col.sub": "40 percursos · 500 fases", "sa.gall.d": "Experimente as 25 regras especiais", "sk.d.u0": "2–3 regras que se movem, de uma vez!", "sk.d.u1": "2–3 regras que mudam como os números aparecem ou são digitados!", "sk.d.u4": "De 2 a 3 das 25 regras, sorteadas."});
add('de', {"g.balloon": "Luftballons", "g.balloon.d": "Luftballons steigen übers Feld — tipp sie an, um sie platzen zu lassen", "sk.n.balloon": "Luftballons", "sk.d.balloon": "Lass Ballons platzen, während du löst!", "g.dark": "Stromausfall", "g.dark.d": "Ab und zu geht das Licht aus — du kannst im Dunkeln weiterschreiben", "sk.n.dark": "Stromausfall", "sk.d.dark": "Licht aus? Keine Panik.", "g.sway": "Schaukelboot", "g.sway.d": "Das Feld schaukelt wie ein Boot", "sk.n.sway": "Schaukelboot", "sk.d.sway": "Ziel gut auf dem schaukelnden Feld.", "g.paint": "Farbe", "g.paint.d": "Farbkleckse verdecken Felder — tipp sie weg", "sk.n.paint": "Farbe", "sk.d.paint": "Wisch die Farbe weg und gib Gas!", "g.order": "Der Reihe nach", "g.order.d": "Nummerierte Felder nur in der Reihenfolge 1, 2, 3 … ausfüllen", "sk.n.order": "Der Reihe nach", "sk.d.order": "Plane, welches Feld wann dran ist.", "g.noline": "Ohne Linien", "g.noline.d": "Die Kastenlinien (ab ★2 alle Linien) verschwinden — merk dir die Kästen", "sk.n.noline": "Ohne Linien", "sk.d.noline": "Erkenne die 4×4-Form ohne Linien.", "g.star": "Sternschnuppen", "g.star.d": "Tipp eine Sternschnuppe an und hol dir +2 Sekunden!", "sk.n.star": "Sternschnuppen", "sk.d.star": "Fang Sterne für mehr Zeit!", "g.rev": "Verkehrte Tasten", "g.rev.d": "Die Tasten tippen die Gegenzahl (1↔4, 2↔3)", "sk.n.rev": "Verkehrte Tasten", "sk.d.rev": "Dreh die Zahlen im Kopf um.", "g.dice": "Würfel", "g.dice.d": "Zahlen werden zu Würfeln — zähl die Augen", "sk.n.dice": "Würfel", "sk.d.dice": "Lies die Augen blitzschnell.", "g.sleepy": "Schläfrig", "g.sleepy.d": "Hörst du auf zu schreiben, döst das Feld ein und wird dunkel — schreib weiter, um es zu wecken", "sk.n.sleepy": "Schläfrig", "sk.d.sleepy": "Zu lange Pause? Gute Nacht …", "sp.tier.6": "Herausforderung", "sp.tier.6.d": "Zehn weitere neue Sonderregeln", "sp.col.sub": "40 Kurse · 500 Stufen", "sa.gall.d": "Probiere alle 25 Sonderregeln", "sk.d.u0": "2–3 Regeln, die sich bewegen, gleichzeitig!", "sk.d.u1": "2–3 Regeln, die Aussehen oder Eingabe der Zahlen ändern!", "sk.d.u4": "2–3 der 25 Regeln, zufällig gemischt."});
add('hi', {"g.balloon": "गुब्बारे", "g.balloon.d": "गुब्बारे बोर्ड पर ऊपर उड़ते हैं — टैप करके फोड़ो", "sk.n.balloon": "गुब्बारे", "sk.d.balloon": "हल करते हुए गुब्बारे फोड़ो!", "g.dark": "बिजली गुल", "g.dark.d": "बीच-बीच में बत्ती चली जाती है — अँधेरे में भी लिख सकते हो", "sk.n.dark": "बिजली गुल", "sk.d.dark": "अँधेरा हो गया? घबराओ मत।", "g.sway": "डगमग नाव", "g.sway.d": "बोर्ड नाव की तरह डगमगाता है", "sk.n.sway": "डगमग नाव", "sk.d.sway": "डगमगाते बोर्ड पर ध्यान से निशाना लगाओ।", "g.paint": "पेंट", "g.paint.d": "पेंट के छींटे खाने ढक देते हैं — टैप करके पोंछो", "sk.n.paint": "पेंट", "sk.d.paint": "पेंट पोंछो और रफ़्तार बनाए रखो!", "g.order": "क्रम से", "g.order.d": "नंबर वाले खाने सिर्फ़ 1, 2, 3… के क्रम में भरे जा सकते हैं", "sk.n.order": "क्रम से", "sk.d.order": "कौन सा खाना कब भरना है, सोचकर चलो।", "g.noline": "बिना लाइन", "g.noline.d": "डिब्बों की मोटी लाइनें (★2 से सारी लाइनें) गायब — डिब्बे याद रखो", "sk.n.noline": "बिना लाइन", "sk.d.noline": "बिना लाइनों के 4×4 आकार पहचानो।", "g.star": "टूटते तारे", "g.star.d": "टूटते तारे को टैप करके पकड़ो और +2 सेकंड पाओ!", "sk.n.star": "टूटते तारे", "sk.d.star": "तारे पकड़ो, समय कमाओ!", "g.rev": "उल्टी चाबियाँ", "g.rev.d": "चाबियाँ उल्टा अंक लिखती हैं (1↔4, 2↔3)", "sk.n.rev": "उल्टी चाबियाँ", "sk.d.rev": "दिमाग़ में अंक उलट दो।", "g.dice": "पासे", "g.dice.d": "अंक पासे बन जाते हैं — बिंदु गिनो", "sk.n.dice": "पासे", "sk.d.dice": "बिंदु झट से पढ़ो।", "g.sleepy": "नींद", "g.sleepy.d": "लिखना रोको तो बोर्ड ऊँघकर धुँधला हो जाता है — लिखते रहो और उसे जगाओ", "sk.n.sleepy": "नींद", "sk.d.sleepy": "ज़्यादा रुके तो शुभ रात्रि…", "sp.tier.6": "चुनौती", "sp.tier.6.d": "दस और नए खास नियम", "sp.col.sub": "40 कोर्स · 500 स्टेज", "sa.gall.d": "सारे 25 खास नियम आज़माओ", "sk.d.u0": "घूमने-फिरने वाले 2–3 नियम एक साथ!", "sk.d.u1": "अंकों का रूप या इनपुट बदलने वाले 2–3 नियम एक साथ!", "sk.d.u4": "25 में से 2–3 नियम, बिल्कुल रैंडम।"});
add('ar', {"g.balloon": "بالونات", "g.balloon.d": "بالونات تطفو فوق اللوحة — المسها لتفرقعها", "sk.n.balloon": "بالونات", "sk.d.balloon": "فرقع البالونات وأنت تحل!", "g.dark": "انقطاع الكهرباء", "g.dark.d": "ينطفئ النور من حين لآخر — يمكنك الكتابة في الظلام", "sk.n.dark": "انقطاع الكهرباء", "sk.d.dark": "انطفأ النور؟ لا تقلق.", "g.sway": "قارب متمايل", "g.sway.d": "اللوحة تتمايل مثل قارب", "sk.n.sway": "قارب متمايل", "sk.d.sway": "صوّب جيدًا على لوحة تتمايل.", "g.paint": "طلاء", "g.paint.d": "بقع طلاء تغطي الخانات — المسها لتمسحها", "sk.n.paint": "طلاء", "sk.d.paint": "امسح الطلاء وواصل السباق!", "g.order": "بالترتيب", "g.order.d": "الخانات المرقّمة تُملأ فقط بالترتيب 1، 2، 3…", "sk.n.order": "بالترتيب", "sk.d.order": "خطّط لأي خانة تملؤها ومتى.", "g.noline": "بلا خطوط", "g.noline.d": "تختفي خطوط المربعات (ومن ★2 كل الخطوط) — تذكّر مكان المربعات", "sk.n.noline": "بلا خطوط", "sk.d.noline": "اكتشف شكل 4×4 دون خطوط.", "g.star": "شهب", "g.star.d": "المس شهابًا لتلتقطه وتربح +2 ثانية!", "sk.n.star": "شهب", "sk.d.star": "التقط النجوم لتربح وقتًا!", "g.rev": "مفاتيح معاكسة", "g.rev.d": "المفاتيح تكتب الرقم المعاكس (1↔4، 2↔3)", "sk.n.rev": "مفاتيح معاكسة", "sk.d.rev": "اقلب الأرقام في رأسك.", "g.dice": "نرد", "g.dice.d": "تتحول الأرقام إلى نرد — عُدّ النقاط", "sk.n.dice": "نرد", "sk.d.dice": "اقرأ النقاط في لمح البصر.", "g.sleepy": "نعسان", "g.sleepy.d": "إذا توقفت عن الكتابة تغفو اللوحة وتُعتم — واصل لتوقظها", "sk.n.sleepy": "نعسان", "sk.d.sleepy": "توقفت طويلًا؟ تصبح على خير…", "sp.tier.6": "تحدٍّ", "sp.tier.6.d": "عشر قواعد خاصة جديدة أخرى", "sp.col.sub": "40 مسارًا · 500 مرحلة", "sa.gall.d": "جرّب القواعد الخاصة الـ25 كلها", "sk.d.u0": "من 2 إلى 3 قواعد متحركة معًا!", "sk.d.u1": "من 2 إلى 3 قواعد تغيّر شكل الأرقام أو إدخالها معًا!", "sk.d.u4": "من 2 إلى 3 من القواعد الـ25، عشوائيًا."});
